// Verifies X-Postsider-Signature: sha256=<hex HMAC of "<timestamp>.<raw body>">.
const crypto = require('crypto');
const secret = $env.POSTSIDER_WEBHOOK_SECRET;
if (!secret) throw new Error('Set POSTSIDER_WEBHOOK_SECRET to the webhook subscription secret');
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-postsider-timestamp'] || '');
const signature = String(headers['x-postsider-signature'] || '');
const raw = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : '';
const seconds = Number(timestamp);
const ms = seconds < 1e12 ? seconds * 1000 : seconds;
if (!Number.isFinite(ms) || Math.abs(Date.now() - ms) > 5 * 60 * 1000) {
  throw new Error('Rejected: timestamp missing or older than 5 minutes');
}
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + raw).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Rejected: invalid signature');
}
return [{ json: { event: headers['x-postsider-event'], eventId: headers['x-postsider-event-id'], payload: JSON.parse(raw) } }];
